//! 🪡️ Real typed child backing is admitted before its pure header and freed only after its genuine frontier is empty.
use super::*;
use semio_framework_value_native_storage::NativeOwnedStorage;
/// 🧮️ Delegates the actual selected work independently of its physical progress variant.
fn physical<E>(turn:RetainedWorkOutcome<RetainedCloneStep,E>)->RetainedWorkOutcome<RetainedCloneProgress,E>{RetainedWorkOutcome{result:turn.result.map(|s|s.progress()),work:turn.work}}
pub(crate) fn capacity(native:&NativeDecodeControl<'_>,bytes:usize)->Result<(),ValueError>{if native.owned_bytes().checked_add(bytes).is_none_or(|n|n>native.maximum_bytes()){Err(ValueError::literal(ValueRefusalKind::OwnershipLimit,"owned receiving backing exceeds original native limit"))}else{Ok(())}}
pub(crate) fn header_release_demand<C>()->RetirementDemand{RetirementDemand{release_bytes:std::alloc::Layout::new::<C>().size(),depth:1,..Default::default()}}
/// 🧹️ The defining caller proves C's real frontier empty before this fixed backing release; C::Drop is never invoked.
pub(crate) unsafe fn release_empty_header<C>(header:&mut Option<Box<C>>,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress>{if header.is_none(){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}let d=header_release_demand::<C>();if !funds(g,d){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}let layout=std::alloc::Layout::new::<C>();let pointer=Box::into_raw(match header.take(){Some(v)=>v,None=>return RetainedWorkOutcome{result:Err(ValueError::invariant("header absent").into()),work:0}});if layout.size()!=0{unsafe{std::alloc::dealloc(pointer.cast(),layout)}}RetainedWorkOutcome{result:Ok(receipt(d)),work:1}}
/// 🎛️ The actual cursor and its completed header remain in the same owner through every denied or failed call.
pub struct OwnedReceivingSlot<T:DslOwnedReceivingField>{backing:NativeOwnedStorage<T::Cursor>,retired:ManuallyDrop<Option<Box<T::Cursor>>>,closing:bool}
impl<T:DslOwnedReceivingField>OwnedReceivingSlot<T>{
 pub const fn new()->Self{Self{backing:NativeOwnedStorage::empty(),retired:ManuallyDrop::new(None),closing:false}}
 pub fn is_ready(&self)->bool{!self.closing&&self.backing.get().is_some_and(|c|c.is_ready())}
 pub fn demands(&self,source:&Option<FieldValue>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing{return Err(invariant())}if !self.backing.reserved(){return Ok(NativeOwnedStorage::<T::Cursor>::reserve_demand())}if !self.backing.initialized(){return Ok(NativeOwnedStorage::<T::Cursor>::move_demand())}self.backing.get().ok_or_else(invariant)?.demands(source,body).and_then(nested)}
 pub fn step(&mut self,source:&mut Option<FieldValue>,native:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress,OriginalReceivingPrimary>{let d=match self.demands(source,body){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e.into()),work:0}};if !funds(g,d){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}if !self.backing.reserved(){if let Err(e)=capacity(native,d.capacity_bytes){return RetainedWorkOutcome{result:Err(e.into()),work:0}}let turn=self.backing.reserve(g);return physical(native.receive_retained_work(g,turn))}if !self.backing.initialized(){if let Err(e)=native.checkpoint(){return RetainedWorkOutcome{result:Err(e.into()),work:0}}let mut header=Some(T::receiving_cursor());let turn=physical(self.backing.put_from(&mut header,g));return RetainedWorkOutcome{result:turn.result.map_err(Into::into),work:turn.work}}match self.backing.get_mut(){Some(v)=>v,None=>return RetainedWorkOutcome{result:Err(ValueError::invariant("get_mut target absent").into()),work:0}}.step(source,native,body,child_grant(g))}
 pub fn take_into(&mut self,output:&mut Option<T>,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress>{if self.closing{return RetainedWorkOutcome{result:Err(invariant()),work:0}}let Some(child)=self.backing.get_mut()else{return RetainedWorkOutcome{result:Err(invariant()),work:0}};child.take_into(output,child_grant(g))}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if self.terminal_is_empty(){return Ok(Default::default())}if !self.closing{return Ok(metadata::<()>())}if let Some(header)=self.retired.as_ref(){if !header.terminal_is_empty(){return Err(invariant())}return Ok(header_release_demand::<T::Cursor>())}if let Some(child)=self.backing.get(){return if child.terminal_is_empty(){Ok(NativeOwnedStorage::<T::Cursor>::move_demand())}else{child.close_demands(body).and_then(nested)}}Ok(self.backing.release_demand())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneProgress>{if self.terminal_is_empty(){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}let d=match self.close_demands(g.maximum_copy_bytes){Ok(d)=>d,Err(e)=>return RetainedWorkOutcome{result:Err(e),work:0}};if !funds(g,d){return RetainedWorkOutcome{result:Ok(Default::default()),work:0}}if !self.closing{self.closing=true;return RetainedWorkOutcome{result:Ok(receipt(d)),work:1}}if let Some(header)=self.retired.as_ref(){if !header.terminal_is_empty(){return RetainedWorkOutcome{result:Err(invariant()),work:0}}return unsafe{release_empty_header(&mut self.retired,g)}}if let Some(child)=self.backing.get_mut(){if !child.terminal_is_empty(){return child.close_step(child_grant(g))}let turn=self.backing.take_box(g);let work=turn.work;let result=turn.result.map(|out|if let Some((header,p))=out{*self.retired=Some(header);p}else{Default::default()});return RetainedWorkOutcome{result,work}}physical(self.backing.release(g))}
 pub fn terminal_is_empty(&self)->bool{self.backing.terminal_is_empty()&&self.retired.is_none()}
}
impl<T:DslOwnedReceivingField>Drop for OwnedReceivingSlot<T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"owned receiving child needs paid terminal closure");if self.terminal_is_empty(){unsafe{ManuallyDrop::drop(&mut self.retired)}}}}
